import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matmul_cute(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cuda_pipeline.h>
#include <cute/tensor.hpp>

using namespace cute;

// Kernel: tiled GEMM C = A * B
// A: (M,K) row-major, B: (K,N) row-major, C: (M,N) row-major
template <class TA, class TB, class TC>
__global__ static void __launch_bounds__(512)
gemm_device(cute::Shape<int,int,int> shape_MNK,
            TA const* A, cute::Stride<int,int> dA,
            TB const* B, cute::Stride<int,int> dB,
            TC      * C, cute::Stride<int,int> dC)
{
  using namespace cute;
  // CTA tile sizes
  constexpr int BM = 128;
  constexpr int BN = 64;
  constexpr int BK = 16;
  constexpr int LDB = BN + 4; // skew to reduce shared-memory bank conflicts
  int M = get<0>(shape_MNK);
  int N = get<1>(shape_MNK);
  int K = get<2>(shape_MNK);
  int lda = get<0>(dA); // A (M,K) row-major
  int ldb = get<1>(dB); // B (K,N) row-major (dB was the (N,K) view stride (1,N))
  int ldc = get<0>(dC); // C (M,N) row-major
  // Double-buffered shared memory: sA (BM,BK) row-major, sB (BK,BN) row-major+skew
  alignas(16) __shared__ TA smemA[2][BM * BK];
  alignas(16) __shared__ TB smemB[2][BK * LDB];
  int tid = threadIdx.x;
  int bm = blockIdx.x * BM;
  int bn = blockIdx.y * BN;
  // Global -> shared copy indices: 16B vectors (float4).
  // With 512 threads, A needs exactly one float4 per thread; B needs one for tid < 256.
  int a_row = tid >> 2;
  int a_col = (tid & 3) * 4;
  int b_row = tid >> 4;
  int b_col = (tid & 15) * 4;
  const float4* gA0 = reinterpret_cast<const float4*>(A + (bm + a_row) * lda + a_col);
  const float4* gB = nullptr;
  if (tid < 256) {
    gB = reinterpret_cast<const float4*>(B + b_row * ldb + bn + b_col);
  }
  // Asynchronous global->shared staged copy (cp.async), one k-tile per stage
  auto load_tile = [&](int kt, int stage) {
    float4* sA0 = reinterpret_cast<float4*>(&smemA[stage][a_row * BK + a_col]);
    __pipeline_memcpy_async(sA0, gA0 + kt * (BK / 4), 16);
    if (tid < 256) {
      float4* sB = reinterpret_cast<float4*>(&smemB[stage][b_row * LDB + b_col]);
      __pipeline_memcpy_async(sB, gB + kt * (BK * ldb / 4), 16);
    }
    __pipeline_commit();
  };
  // Occupancy-oriented remap: 512 threads as 16 warps in a 4x4 grid.
  // Warp tile is 32x16 and thread tile is 4x4, cutting accumulators from 32 to 16
  // while keeping the same 128x64 CTA tile and shared-memory footprint.
  int warp = tid >> 5;   // 0..15
  int lane = tid & 31;   // 0..31
  int warp_m = warp >> 2; // 0..3
  int warp_n = warp & 3;  // 0..3
  int tm = lane >> 2;    // 0..7
  int tn = lane & 3;     // 0..3
  int m0 = warp_m * 32 + tm * 4;
  int n0 = warp_n * 16 + tn * 4;
  float acc[4][4];
  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    #pragma unroll
    for (int j = 0; j < 4; ++j) acc[i][j] = 0.0f;
  }
  int k_tiles = K / BK;
  load_tile(0, 0);
  // Pipelined main loop: prefetch next k-tile while computing current one
  for (int kt = 0; kt < k_tiles; ++kt) {
    int stage = kt & 1;
    bool has_next = (kt + 1 < k_tiles);
    if (has_next) load_tile(kt + 1, 1 - stage);
    __pipeline_wait_prior(has_next ? 1 : 0);
    __syncthreads();
    const float* sA = &smemA[stage][0];
    const float* sB = &smemB[stage][0];
    #pragma unroll
    for (int kk = 0; kk < BK; kk += 4) {
      // Conflict-free vectorized smem reads of B (lanes consecutive along N)
      float4 b0 = *reinterpret_cast<const float4*>(&sB[(kk + 0) * LDB + n0]);
      float4 b1 = *reinterpret_cast<const float4*>(&sB[(kk + 1) * LDB + n0]);
      float4 b2 = *reinterpret_cast<const float4*>(&sB[(kk + 2) * LDB + n0]);
      float4 b3 = *reinterpret_cast<const float4*>(&sB[(kk + 3) * LDB + n0]);
      #pragma unroll
      for (int i = 0; i < 4; ++i) {
        float4 a = *reinterpret_cast<const float4*>(&sA[(m0 + i) * BK + kk]);
        acc[i][0] += a.x * b0.x + a.y * b1.x + a.z * b2.x + a.w * b3.x;
        acc[i][1] += a.x * b0.y + a.y * b1.y + a.z * b2.y + a.w * b3.y;
        acc[i][2] += a.x * b0.z + a.y * b1.z + a.z * b2.z + a.w * b3.z;
        acc[i][3] += a.x * b0.w + a.y * b1.w + a.z * b2.w + a.w * b3.w;
      }
    }
    __syncthreads();
  }
  // Epilogue: vectorized global stores
  #pragma unroll
  for (int i = 0; i < 4; ++i) {
    *reinterpret_cast<float4*>(C + (bm + m0 + i) * ldc + bn + n0) =
        make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
  }
}

// Host wrapper
torch::Tensor matmul_cute(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");

  // A:[M,K], B:[K,N] -> C = A @ B
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0)==K, "B.size(0) must equal A.size(1)");
  TORCH_CHECK(M % 128 == 0 && N % 64 == 0 && K % 16 == 0,
              "This kernel requires M divisible by 128, N divisible by 64 and K divisible by 16");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());

  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();

  // Row-major A (M,K): (m,k) at m*K + k
  auto dA = make_stride(K, 1);
  // B (K,N) row-major viewed as B^T (N,K): (n,k) at k*N + n
  auto dB = make_stride(1, N);
  // Row-major C (M,N): (m,n) at m*N + n
  auto dC = make_stride(N, 1);
  auto shape_MNK = make_shape(M, N, K);

  dim3 dimBlock(512);
  dim3 dimGrid((M+127)/128, (N+63)/64);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_device<<<dimGrid, dimBlock, 0, stream>>>(shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cute_matmul_ext = load_inline(
    name="cute_matmul_inline",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["matmul_cute"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Square matrix multiplication C = A * B implemented with a single
    custom tiled CUTE CUDA GEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matmul_cute(A.contiguous(), B.contiguous())

